/* Generated by quickwins/build.py from content/*.csv. KJV text verified against bible-api.com (translation=kjv). */
window.TB_DAYS=[{"theme": "Faith", "teen": {"ref": "Hebrews 11:1", "text": "Now faith is the substance of things hoped for, the evidence of things not seen."}, "adult": {"ref": "Colossians 3:23", "text": "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;", "note": "Monday meetings, spreadsheets, school runs: none of it is small when it's offered to God."}, "night": {"ref": "Matthew 11:28", "text": "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", "note": "You carried a lot today. You don't have to carry it into tonight."}, "story": "Noah hammering beams under a dry, cloudless sky while neighbors laugh and jeer from the ridge. Pip deadpans, 'So... no forecast, no water, just vibes?' Lumi answers with the verse, and then the first raindrop hits the deck: a slow-motion, goosebumps beat.", "prayer": "God, help me build today on what You promised, even before I can see it. Amen."}, {"theme": "Courage", "teen": {"ref": "Joshua 1:9", "text": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest."}, "adult": {"ref": "Isaiah 41:10", "text": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.", "note": "Before the inbox, the news and the to-do list, hear this: He is with you and He will hold you up."}, "night": {"ref": "1 Peter 5:7", "text": "Casting all your care upon him; for he careth for you.", "note": "Name the worries out loud, one by one, and hand each one over before you sleep."}, "story": "Benny tells the story in talking-head cuts, with animated flashbacks of the robotics showcase, the mic feedback and 600 faces staring at him. Pip pops into frame: 'Spoiler, he survived.' Lumi lands on the podium and speaks the verse, and in the flashback Benny breathes, restarts and nails it.", "prayer": "Lord, when I'm scared, remind me You walk in first. Amen."}, {"theme": "Kindness", "teen": {"ref": "Ephesians 4:32", "text": "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you."}, "adult": {"ref": "Proverbs 16:3", "text": "Commit thy works unto the LORD, and thy thoughts shall be established.", "note": "Clarity often comes after commitment. Give Him the plan, then take the next step."}, "night": {"ref": "Psalm 4:8", "text": "I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.", "note": "Locks and alarms help, but your real safety tonight is the Lord Himself."}, "story": "Shot from Gracie's POV in the cafeteria, the two choices appear as game-style prompts: [Keep scrolling] or [Sit down]. Pip, from her backpack: 'If you pick scrolling, I'm telling Grandpa.' She sits down. Lumi speaks the verse over a slow-motion moment of the new kid smiling for the first time all week.", "prayer": "Jesus, make me the kind one in the room today, especially when it costs me something. Amen."}, {"theme": "Gratitude", "teen": {"ref": "1 Thessalonians 5:18", "text": "In every thing give thanks: for this is the will of God in Christ Jesus concerning you."}, "adult": {"ref": "Ecclesiastes 4:9-10", "text": "Two are better than one; because they have a good reward for their labour. For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.", "note": "Marriage isn't two people never falling. It's two people refusing to let the other stay down."}, "night": {"ref": "Ephesians 4:26", "text": "Be ye angry, and sin not: let not the sun go down upon your wrath:", "note": "Anger isn't the sin. Letting it settle in overnight is. Who do you need to make peace with before you sleep?"}, "story": "A fast, cozy-aesthetic montage cut to the beat: Grandpa Eli's burnt pancakes, Gracie's half-finished sketchbook, Benny's robot face-planting, Wren asleep mid-chirp, an autumn sunset. Each clip gets a handwritten caption ('Grandpa's terrible pancakes 10/10'). Lumi closes on the verse as the last shot holds on the family laughing.", "prayer": "Father, open my eyes to the small gifts I'd usually scroll past. Thank You. Amen."}, {"theme": "Forgiveness", "teen": {"ref": "Colossians 3:13", "text": "Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye."}, "adult": {"ref": "2 Timothy 1:7", "text": "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.", "note": "Fear is a feeling, not a calling. You've been given power, love and a sound mind for today."}, "night": {"ref": "Philippians 4:6-7", "text": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.", "note": "\"Be careful for nothing\" means \"don't be anxious about anything.\" Trade the worry for a thank-you and a request."}, "story": "Joseph, now ruler of Egypt, stands over the brothers who sold him as they kneel, terrified and starving. The score drops out; Pip whispers, 'Okay, this is the revenge arc, right?' Instead Joseph breaks down weeping and embraces them, and Lumi speaks the verse.", "prayer": "God, I don't want to carry this grudge any more. Help me let it go the way You let mine go. Amen."}, {"theme": "Hope", "teen": {"ref": "Jeremiah 29:11", "text": "For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end."}, "adult": {"ref": "Psalm 90:17", "text": "And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.", "note": "Ask God to make what you build today last longer than the deadline."}, "night": {"ref": "Psalm 46:10", "text": "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.", "note": "Five quiet minutes, no screens. Stillness is where knowing happens."}, "story": "Gracie's phone screen fills the frame as she texts Benny that she didn't make the art academy. Typing dots appear and disappear. Pip reads over her shoulder: 'He's typing a novel.' Benny's reply is a screenshot of the verse, with Lumi's glow pulsing across the screen as she reads it aloud.", "prayer": "Lord, when my plans fall apart, hold my future steady. Amen."}, {"theme": "Peace", "teen": {"ref": "John 14:27", "text": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."}, "adult": {"ref": "Micah 6:8", "text": "He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?", "note": "Do justly, love mercy, walk humbly: a whole job description in one verse."}, "night": {"ref": "Matthew 5:4", "text": "Blessed are they that mourn: for they shall be comforted.", "note": "If you're grieving this season, your tears are not a lack of faith. Comfort is promised."}, "story": "The Sea of Galilee at night, the boat pitching, waves exploding over the deck and the disciples bailing in panic. Pip, soaked and clinging to the mast: 'Is NOBODY going to wake Him up?!' Jesus rises and the storm goes still in a single breath. Lumi speaks the verse in the eerie, perfect calm.", "prayer": "Jesus, speak peace over the storm in my head tonight. Amen."}, {"theme": "Friendship", "teen": {"ref": "Proverbs 17:17", "text": "A friend loveth at all times, and a brother is born for adversity."}, "adult": {"ref": "Proverbs 27:17", "text": "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.", "note": "Adult friendships take intention. Text the friend who makes you better."}, "night": {"ref": "Psalm 147:3", "text": "He healeth the broken in heart, and bindeth up their wounds.", "note": "Some wounds don't show. God sees them all, and He's gentle with them."}, "story": "Gracie sees the Instagram story: her whole friend group at the fall festival, no invite. Pip, flatly: 'Cool cool cool. Love that for them.' Then Wren shows up at the door with two hot ciders, and Benny is right behind him. Lumi speaks the verse as the three of them have the better night.", "prayer": "God, make me a friend who shows up, and send me friends who do the same. Amen."}, {"theme": "Strength", "teen": {"ref": "Philippians 4:13", "text": "I can do all things through Christ which strengtheneth me."}, "adult": {"ref": "Isaiah 43:19", "text": "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.", "note": "A new job, a move, an empty nest: God specializes in roads through wilderness."}, "night": {"ref": "Isaiah 26:3", "text": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.", "note": "Where your mind rests tonight matters. Set it on Him."}, "story": "A dim Roman prison, chains clinking, as Paul writes by a sliver of light. Pip squints: 'Wait. He wrote the gym verse... here?' Lumi explains that Paul meant strength for any situation, full or hungry, free or chained, and speaks the verse as the light falls across the page.", "prayer": "Christ, be my strength where I've run out of my own. Amen."}, {"theme": "Trust", "teen": {"ref": "Proverbs 3:5-6", "text": "Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths."}, "adult": {"ref": "Philippians 1:6", "text": "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:", "note": "You're not a finished project, and God isn't a quitter."}, "night": {"ref": "Matthew 6:34", "text": "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.", "note": "Tomorrow's problems get tomorrow's grace. Tonight, rest."}, "story": "Rapid-fire cuts: Gracie with three color-coded planners, Benny re-checking his robot's code at 2 AM, Wren with 47 browser tabs open titled 'what if.' Lumi lands on the planner and speaks the verse. Final shot: Gracie closes one planner and actually goes to sleep.", "prayer": "Lord, I hand You my planner, my worries and my what-ifs. Lead the way. Amen."}, {"theme": "Anxiety / God's Care", "teen": {"ref": "Matthew 6:26", "text": "Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?"}, "adult": {"ref": "Ephesians 2:10", "text": "For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.", "note": "You were designed on purpose, for purpose. Today has good works already waiting."}, "night": {"ref": "Psalm 30:5", "text": "For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.", "note": "If tonight is a weeping night, hold on. Morning is coming."}, "story": "Wren spirals in bed, and his thoughts appear as floating doomscroll notifications. Pip, half asleep: 'Bro. You're a bird. You don't even have a 401(k).' Lumi glows on and points out the window at the birds that are fed every single day, then speaks the verse.", "prayer": "Father, You feed the birds. Remind my anxious heart that You've got me too. Amen."}, {"theme": "Love", "teen": {"ref": "1 John 4:19", "text": "We love him, because he first loved us."}, "adult": {"ref": "Joshua 24:15 (closing words)", "text": "but as for me and my house, we will serve the LORD.", "note": "Whatever the culture chooses, you can set the direction for your home."}, "night": {"ref": "Revelation 21:4", "text": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.", "note": "For everyone missing someone: this is not the end of the story."}, "story": "A ragged son trudges up a dusty road, rehearsing his apology. Far off, his father sees him and RUNS, robes flying, which was undignified for a man in that culture. Pip, quietly: 'He didn't even let him finish the speech.' Lumi speaks the verse over the embrace.", "prayer": "God, You loved me first. Help me love like that. Amen."}, {"theme": "Let Your Light Shine", "teen": {"ref": "Matthew 5:16", "text": "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."}, "adult": {"ref": "Proverbs 31:25", "text": "Strength and honour are her clothing; and she shall rejoice in time to come.", "note": "Put on strength and dignity before you put on anything else today."}, "night": {"ref": "Psalm 62:1", "text": "Truly my soul waiteth upon God: from him cometh my salvation.", "note": "Waiting rooms, test results, unanswered emails: let your soul wait on Him instead."}, "story": "Lumi does a dramatic 'glow-up' transition, from one tiny flicker to blazing gold, and the light spreads as the family hands out cocoa and lanterns at a dark Halloween-night street. Each act of kindness lights another porch until the whole valley is glowing. Lumi speaks the verse over a drone-style wide shot.", "prayer": "Jesus, let my life point people to You, not to me. Amen."}, {"theme": "The Good Shepherd", "teen": {"ref": "Psalm 23:1", "text": "The LORD is my shepherd; I shall not want."}, "adult": {"ref": "James 1:2-3", "text": "My brethren, count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience.", "note": "The hard thing you're facing is building something in you that a comfortable life never could."}, "night": {"ref": "Psalm 127:2", "text": "It is vain for you to rise up early, to sit up late, to eat the bread of sorrows: for so he giveth his beloved sleep.", "note": "Burning the candle at both ends isn't faithfulness. Sleep is a gift from God, too."}, "story": "Young David alone on a moonlit hillside as a lion drags off a lamb. Pip gasps and covers his eyes. David charges, the action stays in silhouette, and he returns cradling the lamb. Pip, shaky: 'He'd do that... for one of us?' Lumi speaks the verse.", "prayer": "Good Shepherd, lead me today. I'll follow. Amen."}, {"theme": "Joy", "teen": {"ref": "Psalm 118:24", "text": "This is the day which the LORD hath made; we will rejoice and be glad in it."}, "adult": {"ref": "Romans 12:2", "text": "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.", "note": "Your feed shapes your mind. Fill it today with something that renews it."}, "night": {"ref": "Mark 6:31", "text": "And he said unto them, Come ye yourselves apart into a desert place, and rest a while: for there were many coming and going, and they had no leisure so much as to eat.", "note": "Even Jesus pulled His team away to rest. You're allowed to step back."}, "story": "Chaos captions stack up: Benny's alarm didn't go off, Grandpa Eli's pancakes are on fire, Wren lost his homework, and it's raining sideways. Pip dances anyway, ridiculously, in the kitchen. Lumi joins the dance and speaks the verse, and by the end the whole family is dancing.", "prayer": "Lord, even on a chaotic day, help me find a reason to be glad. Amen."}, {"theme": "Patience", "teen": {"ref": "Isaiah 40:31", "text": "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."}, "adult": {"ref": "1 Corinthians 15:58", "text": "Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.", "note": "Unseen effort is not wasted effort. Not one hour given to Him is in vain."}, "night": {"ref": "1 Corinthians 13:7", "text": "Beareth all things, believeth all things, hopeth all things, endureth all things.", "note": "Love in marriage is less fireworks and more endurance. Thank God for the person who stays."}, "story": "David, anointed but hunted, shelters in a cave while soldiers' torches pass outside. Pip, frustrated: 'Why didn't God just fast-forward?' Lumi explains that the waiting was forming him, and speaks the verse as an eagle rises past the cave mouth into the dawn.", "prayer": "God, teach me to wait well and trust Your timing. Amen."}, {"theme": "Helping Others", "teen": {"ref": "Galatians 6:2", "text": "Bear ye one another's burdens, and so fulfil the law of Christ."}, "adult": {"ref": "Psalm 37:5", "text": "Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.", "note": "Commit, trust, and let God handle the outcome."}, "night": {"ref": "Psalm 103:2", "text": "Bless the LORD, O my soul, and forget not all his benefits:", "note": "Before bed, name three things He did today. Gratitude remembers."}, "story": "In talking-head cuts, Gracie explains that Benny stayed up every night that week tutoring her at the kitchen table with flashcards and terrible chemistry puns. Pip: 'The puns were the real burden.' Lumi speaks the verse as the flashback shows the B-minus taped to the fridge.", "prayer": "Jesus, show me whose load I can help carry today. Amen."}, {"theme": "Identity", "teen": {"ref": "Psalm 139:14", "text": "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well."}, "adult": {"ref": "Ephesians 4:2", "text": "With all lowliness and meekness, with longsuffering, forbearing one another in love;", "note": "Patience with your spouse today might be the most spiritual thing you do."}, "night": {"ref": "Psalm 55:22", "text": "Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.", "note": "Bills, diagnoses, deadlines: whatever weighs on you, He can carry it."}, "story": "Gracie scrolls perfect filtered faces, then catches her reflection in the dark phone screen. Pip leans in: 'Fun fact: that girl in the ad has three filters and a ring light.' Lumi glows on the mirror and speaks the verse, and the filters peel away from the feed one by one.", "prayer": "Creator, when I compare myself, remind me You made me on purpose. Amen."}, {"theme": "Overcoming Fear", "teen": {"ref": "Psalm 56:3", "text": "What time I am afraid, I will trust in thee."}, "adult": {"ref": "Proverbs 22:6", "text": "Train up a child in the way he should go: and when he is old, he will not depart from it.", "note": "Small, faithful moments with your kids add up to a lifetime."}, "night": {"ref": "2 Corinthians 4:16", "text": "For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day.", "note": "Aging bodies, tired eyes: your inner self is still being renewed."}, "story": "David, recognized in Gath, the Philistine city, surrounded by guards, sweating as whispers spread. Pip: 'Oh, he's SO caught.' David writes on a scrap of parchment by firelight, and Lumi speaks the verse as he fakes madness, scratching at the gate and letting spit run down his beard, to slip away (1 Samuel 21).", "prayer": "Lord, when fear shows up, I'm choosing to trust You. Amen."}, {"theme": "Honesty", "teen": {"ref": "Proverbs 12:22", "text": "Lying lips are abomination to the LORD: but they that deal truly are his delight."}, "adult": {"ref": "Psalm 27:1", "text": "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?", "note": "Name the fear. Then ask the question David asked: whom shall I fear?"}, "night": {"ref": "Romans 8:28", "text": "And we know that all things work together for good to them that love God, to them who are the called according to his purpose.", "note": "Not everything is good. But God works all things toward good."}, "story": "Benny's group-project partner slides over the leaked answer key, and the classroom freezes as game-style choices appear. Pip, side-eye: 'Nobody would know. Except, you know... God. And me. I'm right here.' Benny slides it back, and Lumi speaks the verse.", "prayer": "God, give me the courage to tell the truth, even when it's easier not to. Amen."}, {"theme": "Generosity", "teen": {"ref": "2 Corinthians 9:7", "text": "Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver."}, "adult": {"ref": "Hebrews 12:1", "text": "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,", "note": "What weight can you put down today to run lighter?"}, "night": {"ref": "Psalm 91:1", "text": "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.", "note": "Tonight, dwell. Don't just visit God's presence. Stay there."}, "story": "A huge restless crowd on a hillside at sunset as the disciples panic over the cost. A boy steps forward holding five loaves and two fish. Pip: 'Respectfully, that's a snack.' Jesus gives thanks, the baskets keep filling, and Lumi speaks the verse.", "prayer": "Jesus, make me generous with what I have, even when it feels small. Amen."}, {"theme": "Prayer", "teen": {"ref": "Matthew 7:7", "text": "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:"}, "adult": {"ref": "Deuteronomy 8:18", "text": "But thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth, that he may establish his covenant which he sware unto thy fathers, as it is this day.", "note": "Paycheck or pinch, your ability to provide comes from Him."}, "night": {"ref": "Romans 15:13", "text": "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.", "note": "Hope isn't wishful thinking. It's a gift the Spirit pours in."}, "story": "Quick-cut list: Benny asking for help BEFORE the robot catches fire. Gracie texting 'can we talk?' instead of ghosting. Wren praying before spiraling, for once. Lumi caps it off by speaking the verse while knocking on a glowing door that swings open.", "prayer": "Father, I'm asking, seeking and knocking. Thank You for listening. Amen."}, {"theme": "Fresh Start", "teen": {"ref": "Lamentations 3:22-23", "text": "It is of the LORD's mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness."}, "adult": {"ref": "Galatians 5:22-23", "text": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law.", "note": "Which fruit is hardest for you today? Ask for that one."}, "night": {"ref": "Psalm 121:1-2", "text": "I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD, which made heaven and earth.", "note": "Look up from the screen. Your help comes from the Maker of heaven and earth."}, "story": "Peter by a courtyard fire, denying Jesus three times, then the rooster crows and he runs off weeping. Days later, at dawn on a beach, the risen Jesus is cooking breakfast. Pip whispers, 'Is this... the morning after?' Lumi speaks the verse as Peter splashes toward the shore.", "prayer": "Lord, thank You that Your mercy is new this morning. I'm starting again with You. Amen."}, {"theme": "Humility", "teen": {"ref": "Philippians 2:3", "text": "Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves."}, "adult": {"ref": "Psalm 118:6", "text": "The LORD is on my side; I will not fear: what can man do unto me?", "note": "Walk into the room today knowing whose side you're on."}, "night": {"ref": "Romans 8:38-39", "text": "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.", "note": "Nothing you did today, and nothing waiting tomorrow, can separate you from His love."}, "story": "Benny's team wins regionals, and he's mid-victory-lap in his own head (rendered as an epic slow-mo stadium fantasy). Pip pulls the plug on the fantasy: 'Your teammate Maya wrote half that code.' Benny hands Maya the mic, and Lumi speaks the verse.", "prayer": "God, keep me humble when I win and kind when others do. Amen."}, {"theme": "Small Beginnings", "teen": {"ref": "Zechariah 4:10 (first line)", "text": "For who hath despised the day of small things?"}, "adult": {"ref": "Nehemiah 8:10 (closing words)", "text": "for the joy of the LORD is your strength.", "note": "Running on empty? Joy in God is fuel, not decoration."}, "night": {"ref": "Exodus 14:14", "text": "The LORD shall fight for you, and ye shall hold your peace.", "note": "Some battles aren't yours to fight. Hold your peace tonight."}, "story": "Gracie's day-in-the-life vlog: sketching in class, painting after homework, uploading to 3 views (one of them Grandpa Eli, who comments 'Very nice. -Grandpa'). Pip: 'Honestly, iconic comment.' Lumi speaks the verse, then a 'Day 100' card shows her art hanging at a local café.", "prayer": "Lord, bless my small beginnings and help me not to quit. Amen."}, {"theme": "Grief", "teen": {"ref": "Psalm 34:18", "text": "The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit."}, "adult": {"ref": "Esther 4:14 (closing words)", "text": "and who knoweth whether thou art come to the kingdom for such a time as this?", "note": "Your job, your neighborhood, your family: you're there on purpose."}, "night": {"ref": "Psalm 16:11", "text": "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.", "note": "Whatever path tomorrow brings, fullness of joy is found in His presence."}, "story": "Grandpa Eli sits in his woodshop holding Grandma's old reading glasses, his first fall without her. Benny comes in and sits beside him, saying nothing. Pip, for once, doesn't make a joke and leans against Grandpa's leg. Lumi's glow fills the room gently as she speaks the verse.", "prayer": "God, be close to every broken heart tonight, including mine. Amen."}, {"theme": "Wisdom", "teen": {"ref": "James 1:5", "text": "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."}, "adult": {"ref": "Proverbs 4:23", "text": "Keep thy heart with all diligence; for out of it are the issues of life.", "note": "Guard what you watch, who you listen to and what you replay. It all flows from the heart."}, "night": {"ref": "Hebrews 13:5", "text": "Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.", "note": "Lonely or wanting more? Contentment grows from His promise: never alone."}, "story": "Young King Solomon, overwhelmed on a too-big throne, prays at night for wisdom instead of riches. Pip: 'Not even a little gold? Respect.' Smash-cut to Solomon's famous judgment between two mothers, with real stakes, and Lumi speaks the verse.", "prayer": "Father, I need wisdom. Thank You for giving it freely. Amen."}, {"theme": "Perseverance", "teen": {"ref": "Galatians 6:9", "text": "And let us not be weary in well doing: for in due season we shall reap, if we faint not."}, "adult": {"ref": "Isaiah 40:29", "text": "He giveth power to the faint; and to them that have no might he increaseth strength.", "note": "Running on four hours of sleep and caffeine? He gives power to the faint."}, "night": {"ref": "Psalm 73:26", "text": "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.", "note": "When your body or your heart gives out, God is still your portion."}, "story": "Nehemiah's builders work with a trowel in one hand and a sword at their side while enemies taunt from the ridge. Pip: 'This is the most stressful group project ever.' The last stone drops into place and Lumi speaks the verse.", "prayer": "Jesus, when I'm tired of doing right, give me strength to keep going. Amen."}, {"theme": "Peacemaking", "teen": {"ref": "Matthew 5:9", "text": "Blessed are the peacemakers: for they shall be called the children of God."}, "adult": {"ref": "2 Corinthians 12:9", "text": "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.", "note": "Your weak spot might be exactly where His power shows up."}, "night": {"ref": "John 16:33", "text": "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.", "note": "Trouble is promised. So is His victory."}, "story": "Animated comment bubbles fly like arrows between Wren and a rival bird over a dumb online argument. Pip, eating popcorn: 'Should I... help? Or keep watching?' Lumi speaks the verse, and Wren types and then deletes a nasty reply, sending 'fair point, my bad' instead.", "prayer": "God, make me a peacemaker online and off. Amen."}, {"theme": "Blessing", "teen": {"ref": "Numbers 6:24-26", "text": "The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace."}, "adult": {"ref": "Psalm 100:4", "text": "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.", "note": "Thanksgiving season starts now. Begin today with thanks before requests."}, "night": {"ref": "Psalm 107:1", "text": "O give thanks unto the LORD, for he is good: for his mercy endureth for ever.", "note": "Thirty days, sixty verses. End tonight with thanks: He is good."}, "story": "The whole family gathers on the hill at sunset, and Lumi rises and speaks the ancient priestly blessing over them. Then her glow spirals into darkness, and a single voice-less beam of light splits the void. Card: 'GENESIS TO GLORY. 12.25.' Pip's eyes go wide: 'Oh, it's THAT story.'", "prayer": "Lord, bless us and keep us, and make Your face shine on us. Amen."}];
window.TB_MOODS=[{"id": "anxious", "label": "Anxious", "ref": "1 Peter 5:7", "text": "Casting all your care upon him; for he careth for you.", "note": "Name the worry. Then hand it over. You were never meant to carry it alone."}, {"id": "thankful", "label": "Thankful", "ref": "Psalm 107:1", "text": "O give thanks unto the LORD, for he is good: for his mercy endureth for ever.", "note": "Gratitude grows when you say it out loud. Tell someone one good thing today."}, {"id": "tired", "label": "Tired", "ref": "Matthew 11:28", "text": "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", "note": "Rest isn't quitting. Jesus literally invites you to it."}, {"id": "brave", "label": "Brave", "ref": "Joshua 1:9", "text": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.", "note": "Whatever you're walking into, you're not walking in alone."}];
